// ============================================================================
// Video_Codec_8K_apb: APB4 register wrapper around Video_Codec_8K_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Video_Codec_8K.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Video_Codec_8K.md
// ============================================================================
module Video_Codec_8K_apb #(
  parameter logic [3:0] AXI_ID = 4'd9
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h7C090100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [20:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd21) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [31:0]   c_bs_addr;
  logic [31:0]   c_ref0_addr;
  logic [31:0]   c_ref1_addr;
  logic [31:0]   c_recon_addr;
  logic [31:0]   c_chroma_addr;
  logic [15:0]   c_stride;
  logic [7:0]    c_pic_w_ctu;
  logic [7:0]    c_pic_h_ctu;
  logic [2:0]    c_ctu_log2;
  logic [2:0]    c_pu_log2;
  logic [1:0]    c_n_refs;
  logic [2:0]    c_mv_log2;
  logic [7:0]    c_bs_words;
  logic [15:0]   c_ctu_gap;
  logic [15:0]   c_ctu_limit;
  logic [31:0]   c_seed;
  logic          c_start;
  logic          c_busy;
  logic          c_err;
  logic          c_cfg_err;
  logic [15:0]   c_ctus;
  logic [15:0]   c_late_cnt;
  logic [31:0]   c_rd_words;
  logic [31:0]   c_wr_words;
  logic [31:0]   c_rd_sum;
  logic [31:0]   c_cycles;
  logic          c_done;
  logic          c_late;
  logic          c_err_irq;
  Video_Codec_8K_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .bs_addr(c_bs_addr),
    .ref0_addr(c_ref0_addr),
    .ref1_addr(c_ref1_addr),
    .recon_addr(c_recon_addr),
    .chroma_addr(c_chroma_addr),
    .stride(c_stride),
    .pic_w_ctu(c_pic_w_ctu),
    .pic_h_ctu(c_pic_h_ctu),
    .ctu_log2(c_ctu_log2),
    .pu_log2(c_pu_log2),
    .n_refs(c_n_refs),
    .mv_log2(c_mv_log2),
    .bs_words(c_bs_words),
    .ctu_gap(c_ctu_gap),
    .ctu_limit(c_ctu_limit),
    .seed(c_seed),
    .start(c_start),
    .busy(c_busy),
    .err(c_err),
    .cfg_err(c_cfg_err),
    .ctus(c_ctus),
    .late_cnt(c_late_cnt),
    .rd_words(c_rd_words),
    .wr_words(c_wr_words),
    .rd_sum(c_rd_sum),
    .cycles(c_cycles),
    .done(c_done),
    .late(c_late),
    .err_irq(c_err_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [2:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_BS_ADDR;   // 12'h014 BS_ADDR
  logic [31:0] r_REF0_ADDR;   // 12'h018 REF0_ADDR
  logic [31:0] r_REF1_ADDR;   // 12'h01C REF1_ADDR
  logic [31:0] r_RECON_ADDR;   // 12'h020 RECON_ADDR
  logic [31:0] r_CHROMA_ADDR;   // 12'h024 CHROMA_ADDR
  logic [31:0] r_PIC;   // 12'h028 PIC
  logic [18:0] r_CODING;   // 12'h02C CODING
  logic [31:0] r_RATE;   // 12'h030 RATE
  logic [31:0] r_SEED;   // 12'h034 SEED
  logic [0:0] p_CMD;   // 12'h038 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_BS_ADDR <= 32'h0;
      r_REF0_ADDR <= 32'h0;
      r_REF1_ADDR <= 32'h0;
      r_RECON_ADDR <= 32'h0;
      r_CHROMA_ADDR <= 32'h0;
      r_PIC <= 32'h0;
      r_CODING <= 19'h5A6;
      r_RATE <= 32'h0;
      r_SEED <= 32'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[2:0] & wmask[2:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_BS_ADDR <= (r_BS_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6]) r_REF0_ADDR <= (r_REF0_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_REF1_ADDR <= (r_REF1_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_RECON_ADDR <= (r_RECON_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_CHROMA_ADDR <= (r_CHROMA_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_PIC <= (r_PIC & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[11]) r_CODING <= (r_CODING & ~wmask[18:0]) | (PWDATA[18:0] & wmask[18:0]);
      if (wr && hit[12]) r_RATE <= (r_RATE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_SEED <= (r_SEED & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[14]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_bs_addr = r_BS_ADDR[31:0];
  assign c_ref0_addr = r_REF0_ADDR[31:0];
  assign c_ref1_addr = r_REF1_ADDR[31:0];
  assign c_recon_addr = r_RECON_ADDR[31:0];
  assign c_chroma_addr = r_CHROMA_ADDR[31:0];
  assign c_stride = r_PIC[15:0];
  assign c_pic_w_ctu = r_PIC[23:16];
  assign c_pic_h_ctu = r_PIC[31:24];
  assign c_ctu_log2 = r_CODING[2:0];
  assign c_pu_log2 = r_CODING[5:3];
  assign c_n_refs = r_CODING[7:6];
  assign c_mv_log2 = r_CODING[10:8];
  assign c_bs_words = r_CODING[18:11];
  assign c_ctu_gap = r_RATE[15:0];
  assign c_ctu_limit = r_RATE[31:16];
  assign c_seed = r_SEED[31:0];
  assign c_start = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_err_irq;
    irq_set[2] = c_late;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_BS_ADDR);
      10'd6: apb_rdata = 32'(r_REF0_ADDR);
      10'd7: apb_rdata = 32'(r_REF1_ADDR);
      10'd8: apb_rdata = 32'(r_RECON_ADDR);
      10'd9: apb_rdata = 32'(r_CHROMA_ADDR);
      10'd10: apb_rdata = 32'(r_PIC);
      10'd11: apb_rdata = 32'(r_CODING);
      10'd12: apb_rdata = 32'(r_RATE);
      10'd13: apb_rdata = 32'(r_SEED);
      10'd15: apb_rdata = 32'({c_cfg_err, c_err, c_busy});
      10'd16: apb_rdata = 32'({c_late_cnt, c_ctus});
      10'd17: apb_rdata = 32'({c_rd_words});
      10'd18: apb_rdata = 32'({c_wr_words});
      10'd19: apb_rdata = 32'({c_rd_sum});
      10'd20: apb_rdata = 32'({c_cycles});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
